Tested with:
```diff
diff --git a/modules/mbedtls/tls_context_mbedtls.cpp b/modules/mbedtls/tls_context_mbedtls.cpp
index 01e52efc44..339cb75bdd 100644
--- a/modules/mbedtls/tls_context_mbedtls.cpp
+++ b/modules/mbedtls/tls_context_mbedtls.cpp
@@ -155,12 +155,14 @@ Error TLSContextMbedTLS::init_server(int p_transport, Ref<TLSOptions> p_options,
 #ifdef TOOLS_ENABLED
 	if (Engine::get_singleton()->is_editor_hint()) {
 		if (!EditorSettings::get_singleton()->get_setting("network/tls/enable_tls_v1.3").operator bool()) {
+			print_line("Editor: Restrict TLS to v1.2");
 			mbedtls_ssl_conf_max_tls_version(&conf, MBEDTLS_SSL_VERSION_TLS1_2);
 		}
 	} else
 #endif
 	{
 		if (!GLOBAL_GET("network/tls/enable_tls_v1.3").operator bool()) {
+			print_line("Project: Restrict TLS to v1.2");
 			mbedtls_ssl_conf_max_tls_version(&conf, MBEDTLS_SSL_VERSION_TLS1_2);
 		}
 	}
@@ -213,12 +215,14 @@ Error TLSContextMbedTLS::init_client(int p_transport, const String &p_hostname,
 #ifdef TOOLS_ENABLED
 	if (Engine::get_singleton()->is_editor_hint()) {
 		if (!EditorSettings::get_singleton()->get_setting("network/tls/enable_tls_v1.3").operator bool()) {
+			print_line("Editor: Restrict TLS to v1.2");
 			mbedtls_ssl_conf_max_tls_version(&conf, MBEDTLS_SSL_VERSION_TLS1_2);
 		}
 	} else
 #endif
 	{
 		if (!GLOBAL_GET("network/tls/enable_tls_v1.3").operator bool()) {
+			print_line("Project: Restrict TLS to v1.2");
 			mbedtls_ssl_conf_max_tls_version(&conf, MBEDTLS_SSL_VERSION_TLS1_2);
 		}
 	}
```

When opening the assetlib in a project where both the editor and project settings are disabled, only the "Editor" message gets printed, so it's working as intended.
